<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner statements · LRC</title><style>body{font:14px system-ui;background:#f4f6f8;margin:28px;color:#17212b}main{max-width:1200px;margin:auto;background:#fff;padding:26px;border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse;margin-top:18px}td,th{text-align:left;padding:10px;border-bottom:1px solid #e6eaed;white-space:nowrap}.success{background:#edf7f3;padding:10px}button,input{padding:7px}</style></head><body><main><p><a href="/">LRC LLC</a> / Accounting / Owner statements</p><h1>Owner statements & payouts</h1><p><a href="{{ route('accounting.payouts.create') }}">+ Prepare statements</a> · <a href="{{ route('accounting.expenses.index') }}">Property expenses</a></p><p>Draft calculations include verified rent collections, the active agreement fee and approved owner-borne expenses. Approval and recording a bank transfer are separate steps.</p>@if(session('success'))<p class="success">{{ session('success') }}</p>@endif<table><tr><th>Payout</th><th>Owner / Property</th><th>Period</th><th>Gross</th><th>Fee</th><th>Expenses</th><th>Net (RWF)</th><th>Status / Action</th></tr>@forelse($payouts as $payout)<tr><td>{{ $payout->payout_number }}</td><td>{{ $payout->owner->legal_name }}<br>{{ $payout->property->name }}</td><td>{{ $payout->period_start->format('d M Y') }} – {{ $payout->period_end->format('d M Y') }}</td><td>{{ number_format((float)$payout->gross_collected,2) }}</td><td>{{ number_format((float)$payout->management_fee,2) }}</td><td>{{ number_format((float)$payout->owner_expenses,2) }}</td><td><strong>{{ number_format((float)$payout->net_amount,2) }}</strong></td><td>{{ ucfirst($payout->status) }}<br>@if($payout->status==='draft' && auth()->user()->hasAnyRole(['super_admin']) && auth()->user()->id !== $payout->prepared_by)<form method="post" action="{{ route('accounting.payouts.approve',$payout) }}">@csrf<input name=